"use client"

import * as React from "react"
import { Toggle as TogglePrimitive } from "@base-ui/react/toggle"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"
import { useSound } from "./sound-provider"

const toggleVariants = cva(
  [
    "inline-flex items-center justify-center gap-2 rounded-md text-sm font-medium",
    "transition-all duration-base ease-out",
    "hover:bg-accent hover:text-accent-foreground",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
    "disabled:pointer-events-none disabled:opacity-50",
    "active:translate-y-px",
    "data-pressed:bg-primary data-pressed:text-primary-foreground data-pressed:border-[var(--primary-rim)]",
    "data-pressed:shadow-[var(--shadow-tactile-control)]",
    "select-none",
  ].join(" "),
  {
    variants: {
      variant: {
        default: "bg-transparent text-muted-foreground",
        outline:
          "border border-border bg-background text-muted-foreground " +
          "hover:border-ring/50 " +
          "data-pressed:border-border",
      },
      size: {
        sm: "h-8 px-2.5",
        default: "h-9 px-3",
        lg: "h-10 px-5",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

const Toggle = React.forwardRef<
  HTMLButtonElement,
  TogglePrimitive.Props & VariantProps<typeof toggleVariants>
>(({ className, variant, size, onPressedChange, ...props }, ref) => {
  const { playClick } = useSound()
  return (
    <TogglePrimitive
      ref={ref}
      className={cn(toggleVariants({ variant, size, className }))}
      onPressedChange={(pressed, eventDetails) => {
        playClick()
        onPressedChange?.(pressed, eventDetails)
      }}
      {...props}
    />
  )
})
Toggle.displayName = "Toggle"

export { Toggle, toggleVariants }
